{
  "identity": {
    "name": "Creations Unlimited",
    "location": "Nampa, Idaho",
    "claims": [
      {
        "statement": "The business operates as Creations Unlimited Machining Inc., established by [redacted] in 1989.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "Creations Unlimited Machining Inc. was established by [redacted] in 1989."
      },
      {
        "statement": "The company's primary facility is located at 175 Shannon Drive in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "Creations Unlimited, 175 Shannon Dr, Nampa, ID, 83687, U.S. [redacted] [redacted]"
      }
    ]
  },
  "industry": {
    "industry": "Precision CNC Machining and Contract Manufacturing",
    "activities": [
      "5-axis CNC precision milling",
      "Quick-turn prototyping",
      "Low to mild volume production (1 to 2,500 pieces)",
      "First article inspection",
      "Overflow contract machining"
    ],
    "claims": [
      {
        "statement": "Creations Unlimited specializes in advanced 5-axis custom CNC machining services for prototype to low volume production parts.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": "Creations Unlimited specializes in advanced 5-axis custom CNC machining services. Prototype to low volume production parts."
      },
      {
        "statement": "The company serves hi-tech, medical device, space, and aerospace industries rather than residential consumers.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "Creations Unlimited continues to provide high quality machining to the hi-tech and medical industries and now have added machining services to the space and aerospace industries."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.creationsultd.com/",
    "claims": [
      {
        "statement": "The company maintains an 18,000 square foot temperature-controlled manufacturing and quality facility in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "We are located in Nampa, Idaho and have a 18,000 square foot, state of the art facility"
      },
      {
        "statement": "The company relocated its operations to Nampa, Idaho in summer 2021 after 32 years of business in California.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "32 Years of Business in California before relocating to Nampa Idaho Summer 2021"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company maintains ISO 9001:2015 and AS9100D quality management certifications.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/certifications",
        "quote": "ISO 9001:2015 and AS9100D Certificate"
      },
      {
        "statement": "The company holds ITAR registration for defense and aerospace manufacturing compliance.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/certifications",
        "quote": "ITAR Registration"
      }
    ],
    "limitations": "The public website displays quality and defense manufacturing registrations (ISO 9001:2015, AS9100D, ITAR) but does not display trade contractor licenses, as it is a machine shop rather than a residential trade contractor."
  },
  "existingSoftware": [
    {
      "product": "Siemens NX CAD/CAM",
      "purpose": "CAD/CAM modeling and machine code simulation for 5-axis milling",
      "evidence": {
        "statement": "The business operates Siemens NX CAD/CAM with full simulation across its 5-axis machinery.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "Siemens NX CAD/CAM with Full Machine Code Simulation for every 5 axis machines"
      }
    },
    {
      "product": "Paperless ERP System",
      "purpose": "Shop-floor production management and job tracking",
      "evidence": {
        "statement": "The shop utilizes a paperless ERP platform accessible via computer terminals at every machine station.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/about",
        "quote": "Paperless ERP with computer terminals at every machine"
      }
    },
    {
      "product": "Zeiss Calypso Software",
      "purpose": "Metrology and automated CMM inspection software",
      "evidence": {
        "statement": "The quality department utilizes Calypso software for its Zeiss Contura CMM scanning.",
        "label": "fact",
        "sourceUrl": "https://www.creationsultd.com/facilities",
        "quote": "CALYPSO SOFTWARE"
      }
    },
    {
      "product": "Squarespace",
      "purpose": "Website hosting and content management",
      "evidence": {
        "statement": "The public website is hosted on Squarespace infrastructure.",
        "label": "inference",
        "sourceUrl": "https://www.creationsultd.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company targets standard turnaround times of returning quotes in under 24 hours and delivering parts within 2 weeks.",
      "label": "fact",
      "sourceUrl": "https://www.creationsultd.com/services",
      "quote": "Quotes are returned in under 24 hours, parts delivered in 2 weeks standard."
    }
  ],
  "problems": [
    {
      "problem": "Creations Unlimited operates in precision contract manufacturing and CNC machining rather than residential home services (HVAC, plumbing, or electrical).",
      "label": "fact",
      "basis": "Documented on https://www.creationsultd.com/ and https://www.creationsultd.com/about where the firm manufactures 5-axis prototype and production components for medical, semiconductor, space, and aerospace clients."
    },
    {
      "problem": "Quoting and production workflows depend on engineering prints, CAD models, and CAM simulations integrated into a specialized paperless ERP, rather than field-service job dispatching.",
      "label": "inference",
      "basis": "Documented on https://www.creationsultd.com/about citing Siemens NX CAD/CAM with machine code simulation and paperless ERP terminals across the machining floor."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Manufacturing ERP and CAD/CAM Suites (e.g., Siemens NX, paperless ERP)",
      "addresses": "B2B aerospace and precision manufacturing quoting, CAD simulation, inspection, and job tracking.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
